quests[11482] = { id = 11482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duty Calls", description = "Hear me, {race}.\n\nDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more information to share, except this:\n\nYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, the situation calls for us to set our differences aside and join forces.\n\nPrepare yourself, friend. This sounds serious.", sourceObjective = "Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.", completion = "Welcome to Sunwell Plateau, cryer - What's that? Oh Scryer, yes of course. Isn't that what I said?\n\nWell, now, let's get a few things straight. There's some serious business going on behind those walls and it's in the interest of both of our people to address it. And since neither of us have the forces to go it alone, we're going to work - TOGETHER. Got that?\n\nNow let's get started, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11488] = { id = 11488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "Welcome to the Sunwell, {class}. Get yourself settled in and contribute however you can - there's much to do!\n\nMe? Yes, I have a little something that needs doing, but I'm not sure you're up to the task.\n\nWe've had a contact embedded in Magisters' Terrace gathering intelligence for us. He's recently failed to report and I'm growing concerned.\n\nThe terrace is just up the rise to the east. The information he was collecting is vital to our mission.\n\nThink you can handle it, {race}?", sourceObjective = "Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters' Terrace and find Tyrith, a blood elf spy.", completion = "...Come closer, {race}... Listen carefully to my words....", sourceObjectiveStatus = "unverified-source-field" }
quests[11490] = { id = 11490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scryer's Scryer", description = "<Tyrith winces in pain as he speaks.>\n\nGo to the terrace... use the orb.\n\n...They're...feeding the sunwell....\n\n <Tyrith gasps for breath.>\n\nHurry... They must be stopped... before they can....\n\n<Tyrith dies.>", sourceObjective = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace.", progress = "Go and peer into the orb, mortal.", completion = "I consider it to be no coincidence that our paths cross this day.\n\nI sense the tendrils of destiny....", sourceObjectiveStatus = "unverified-source-field" }
quests[11492] = { id = 11492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Kill", description = "Welcome to the Sunwell, mortals. Your arrival is indeed timely.\n\nAs you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. Find him, mortals. He must again be stopped.\n\nOther, equally urgent matters require my immediate attention. I shall leave Kael's fate to you. Do not fail.\n\nWith luck, we shall speak again.", sourceObjective = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor at the Shattered Sun Staging Area.", progress = "Well, {class}, I must admit, I wasn't sure I'd see you again.\n\nWhat news do you bring?", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.\n\nI've underestimated you, {race}. Please, accept this on behalf of the Sunwell Offensive - a gift worthy of a hero such as yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[11496] = { id = 11496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctum Wards", description = "Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.\n\nThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.\n\nHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.", sourceObjective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east.", progress = "Have you reactivated the crystal wards, {name}?", completion = "Good work, {name}.  The wards are slowly regaining their power.  The sanctum will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11497] = { id = 11497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.", sourceObjective = "Speak with Ilsa Blusterbrew at Wildhammer Stronghold in Shadowmoon Valley.", completion = "So, me boyo, Nutral, sent ya along did he?  Good man... I'll need ta remember ta send him along a pint fer all o' the business he's sendin' me way.\n\nIf it's the learnin' o' how ta fly right and proper yer after, ye've come ta the right place. No one flies finer than us Wildhammer and those we train. Fer a fee, and not a small one mind ya, I'll teach ya how ta soar through the skies!\n\nAnd when yer done, don't forget ta talk ta Brunn over there about buying one o' these gryphon beauties!", sourceObjectiveStatus = "unverified-source-field" }
quests[11498] = { id = 11498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.", sourceObjective = "Speak with Olrokk at Shadowmoon Village in Shadowmoon Valley.", completion = "Blood and thunder, Nutral sent me another ground grunt! Good man... for a draenei.\n\n<Olrokk spits on the ground near your feet.>\n\nYou've come to the right place if you want to learn how to ride your own mount through the skies. In return for a big sack of gold, I'll teach you what you need to know and not fall dishonorably to your death.\n\nAnd when you're done, don't forget to talk to Dama Wildmane over there about buying one of the windriders from our stable!", sourceObjectiveStatus = "unverified-source-field" }
quests[11499] = { id = 11499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Signet Ring of Prince Kael'thas", description = "{class}, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to do so.", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Signet Ring of Prince Kael'thas. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed at the Magisters' Terrace on Heroic difficulty.", progress = "The Magisters' Terrace must be a very dangerous place indeed being so close to the Sunwell.\n\nI trust that you're not having second thoughts?", completion = "So, the blood elf prince is truly dead this time? A pity, I always thought he had class. To think that one so lofty could be brought down for such a paltry sum.\n\nBut as they say, business is business. Your reward is earned, adventurer.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11500] = { id = 11500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Sisters of Torment", description = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.\n\nMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to earn the bounty, or you will not.", sourceObjective = "Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment. Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.", completion = "Who can say why the demonic sisters needed to be slain? Do you care?\n\nMah'duun thinks you care enough to collect the bounty, though.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11502] = { id = 11502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Halaa", description = "We are not a warlike race, {race}.  However when war comes to our lands, we do not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.", sourceObjective = "Defeat 10 enemy players in Halaa and return to Lakoor in Telaar.", progress = "Is your task done, {name}?", completion = "I thank you, {name}.  Your efforts will not be ignored.", sourceObjectiveStatus = "unverified-source-field" }
quests[11503] = { id = 11503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies, Old and New", description = "Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.", sourceObjective = "Defeat 10 enemy players in Halaa and return to Karrtog in Garadar.", completion = "You bring great honor to our people.  You have our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11505] = { id = 11505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Auchindoun", description = "Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.\n\nAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.\n\nShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.", sourceObjective = "Help the Alliance secure a tower in the Bone Wastes.", progress = "The spirits are restless, {name}.  Have you accomplished your task?", completion = "The spirits are one step closer to resting in peace.  It is good to incur their favor, especially when waging war so close to their place of rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11506] = { id = 11506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Auchindoun", description = "The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.", sourceObjective = "Help the Horde secure a Spirit Tower in the Bone Wastes.", progress = "The spirits of Auchindoun are all around us.  Will they grant us their boon?", completion = "The spirits are closer to finding peace and have bestowed their favor onto us.\n\nA humiliating blow to our enemy that their own ancestors would side against them, even if only temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[11513] = { id = 11513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Mana Cells", description = "I have devised a plan to acquire a power source strong enough for the creation of our portal.\n\nThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.\n\nThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.\n\nJust beware the mana cells' phase wyrm guardians.", sourceObjective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "Did you acquire the mana cells?", completion = "These mana cells are vital to our efforts. We will have the portal to the Sunwell Isle created in no time!\n\nReturn tomorrow and I will send you out to acquire more of them from our Bash'ir 'friends'.", sourceObjectiveStatus = "unverified-source-field" }
quests[11514] = { id = 11514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining the Sunwell Portal", description = "We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard the mana cells.", sourceObjective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "{name}, how fare your efforts to obtain mana cells for us this day?", completion = "These mana cells will continue to power the portal.\n\nReturn tomorrow and I will send you out to obtain more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11515] = { id = 11515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood for Blood", description = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.\n\nThe blood has changed them, given them new powers.  It will also prove their undoing.\n\nObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.", sourceObjective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them. You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon.", progress = "These freaks are a disgrace to our race.  You must destroy them, {name}.", completion = "Fools.  They learned to drain fel energy but did not learn how to retain it.\n\nWe were lucky, {name}.  An experienced felblood would've surely been a formidable opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[11516] = { id = 11516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast the Gateway", description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.\n\nFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.\n\nOnce you've achieved this bring the flare to the gateway.  It will know what to do.", sourceObjective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare. Return to the Legion Gateway with the Unstable Living Flare to destroy it.", progress = "Is it done, {name}?  We must stop further Legion forces from reinforcing Kael'thas.", completion = "Excellent work, {name}.  The demons might repair the gateway in due time.  I suppose we'll just have to blow it up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11517] = { id = 11517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nasuun", description = "I am most glad that you are here, {class}! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", sourceObjective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!", sourceObjectiveStatus = "unverified-source-field" }
quests[11520] = { id = 11520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discovering Your Roots", description = "Greetings, {race}.\n\nI'm afraid I have little to offer here until my reagents are stocked.\n\nOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.\n\nFortunately, I know a secret....\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.", sourceObjective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, {name}, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "These should do nicely, {class}.\n\nI thank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11521] = { id = 11521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rediscovering Your Roots", description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, {name}, once you have collected five of the roots.", sourceObjective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, {name}, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "Excellent work, {name}.\n\nThank you again for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[11523] = { id = 11523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arm the Wards!", description = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", sourceObjective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach.", progress = "Have you reactivated a crystal ward, {name}?", completion = "Good work, {name}.  The wards are slowly regaining their power.  Sun's Reach will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11524] = { id = 11524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erratic Behavior", description = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.\n\nThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.\n\nI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.", sourceObjective = "Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, {name}?", completion = "Good job, {name}.  The sanctum will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11525] = { id = 11525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Conversions", description = "My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.", sourceObjective = "Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, {name}?", completion = "Excellent.  The converted sentries will help to secure our perimeter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11526] = { id = 11526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Magistrix", description = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.\n\nTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.", sourceObjective = "Use the Captured Legion Scroll near the portal at Dawning Square. Once you've gone through the portal, find Magistrix Seyla.", progress = "Keep quiet, {class}.  The Legion's forces watch the south of the gate.", completion = "It's very sweet of Theris to worry about my hide, but we've got bigger problems here.  Much bigger.", sourceObjectiveStatus = "unverified-source-field" }
quests[11528] = { id = 11528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", sourceObjective = "A small tag on this present reads:\n\nHappy holidays, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11531] = { id = 11531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Engine Part", description = "This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen.  Perhaps K. Lee Smallfry might know something about it.", sourceObjective = "Take the Strange Engine Part to K. Lee Smallfry in Telredor.", progress = "Oh goodness!  What've you got there, {name}?", completion = "<K. Lee looks at the engine part and then stares off into the distance for a moment.>\n\nThis is somethin' real special.  Difficulty to say where it's from--like it just fell out of the sky.  I'm gonna hold on to this and pay you for your troubles.\n\nBetween you and me though, I think it's best if we didn't mention this to anyone.\n\n<K. Lee puts on her most charming smile.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11532] = { id = 11532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distraction at the Dead Scar", description = "The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.\n\nI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.\n\nIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", sourceObjective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", progress = "Have you accomplished your mission, {name}?", completion = "You've got some real talent, kid.  Did you ever think of joining the Skyguard?\n\nI jest, {name}.  We need you here if we want to take the docks any time soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11533] = { id = 11533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Air Strikes Must Continue", description = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", sourceObjective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", progress = "Have you accomplished your mission, {name}?", completion = "Any demons we kill today are demons that we do not have to fight tomorrow.  Keep it up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11534] = { id = 11534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nasuun", description = "I am most glad that you are here, {class}! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", sourceObjective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!", sourceObjectiveStatus = "unverified-source-field" }
quests[11535] = { id = 11535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Ready", description = "Supplies are inbound, or so I'm told.\n\nRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.\n\nAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.\n\nThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.\n\nRelieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I need?", completion = "Excellent! We're getting closer....\n\nSoon I'll be able to craft an anvil, then the real work can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11536] = { id = 11536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stop Now....", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I asked for?", completion = "Excellent! This will help me keep our soldiers in weapons and armor.\n\nYour help is truly making a difference!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Must Go On", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you succeeded, {name}?", completion = "Your dedication is exemplary, {name}.  We will show the forces of the Burning Legion what we're capable of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for the Sun's Reach Armory", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you done what I asked of you, {name}?", completion = "Your dedication is exemplary, {name}.  We will take the armory from the forces of the Legion in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Harbor", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", progress = "Have you slain the Dawnblade scum, {name}?", completion = "Excellent work, {class}.  Kael's armies will falter and once we take the harbor we shall deliver the killing blow!", sourceObjectiveStatus = "unverified-source-field" }
quests[11540] = { id = 11540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Dawnblade", description = "We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.\n\nI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", completion = "What thoughts go through Prince Kael'thas Sunstrider's head when he hears of his armies' defeats?\n\nDoes he feel despair?  Helplessness?  Fear?\n\nI sure hope so.", sourceObjectiveStatus = "unverified-source-field" }
quests[11541] = { id = 11541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt the Greengill Coast", description = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.\n\n{class}, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.", sourceObjective = "Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so.", progress = "My scouts tell me that there hasn't yet been enough disruption of the naga today.", completion = "That's enough for today. Slow and steady is the key here. Too much disruption and they'd turn their attention directly upon us; something that we don't want.\n\nCome back again tomorrow and we'll work on it some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11542] = { id = 11542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercept the Reinforcements", description = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", sourceObjective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", progress = "Have you accomplished your task, {name}?", completion = "Well done, {name}.  It should be a long time before the harbor receives any reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[11543] = { id = 11543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Enemy at Bay", description = "We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", sourceObjective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", progress = "Have you accomplished your task, {name}?", completion = "Well done, {name}.  It should be a long time before the harbor receives any reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[11544] = { id = 11544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ata'mal Armaments", description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.", sourceObjective = "Smith Hauthaa needs you to produce 5 Cleansed Ata'mal Metal. Do so by breaking down Ata'mal Armaments on her anvil at the Sun's Reach Armory on the Isle of Quel'Danas.", progress = "I need all of the cleansed Ata'mal metal that I can get my hands on, {class}.", completion = "Thank you, my friend. Now I will be able to fashion more of the special alloy that is going into the creation of our forces' weapons and armor.\n\nAnd, I have some leftover extract from the process, which you'll likely find handy for use on your weapons. Please, take your pick of whichever will serve your purposes.\n\nReturn to me again on the morrow. No doubt I will need more armaments.", sourceObjectiveStatus = "unverified-source-field" }
quests[11545] = { id = 11545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Charitable Donation", description = "We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.\n\nIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.", sourceObjective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, {name}.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11546] = { id = 11546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open for Business", description = "Welcome, {name}.\n\nThere are a number of ways I can assist you in your efforts here.\n\nFor example, I've recently discovered a recipe for a unique elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you what I mean.", sourceObjective = "Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas.", progress = "Have you gathered those berries yet?", completion = "Excellent, {name}.\n\nI hope this will aid you in your efforts here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11547] = { id = 11547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Your Ley Lines", description = "Freeloaders!\n\nYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.\n\nPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.\n\nTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.\n\nPerhaps then you'll appreciate your precious translocations....", sourceObjective = "Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast.", progress = "Have you attuned the crystal yet, {class}?", completion = "Yes, yes. Let's have a look now, shall we?\n\nThings seem to be in order. Very well. Here is your translocator.\n\nIf any of your readings are faulty, there's no telling where you'll end up, and mind you, you'll only have yourself to blame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11548] = { id = 11548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Continued Support", description = "We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.\n\nI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.", sourceObjective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, {name}.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11549] = { id = 11549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Magnanimous Benefactor", description = "You've done so much for us, {name}.  We greatly appreciate your assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.\n\nIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?", sourceObjective = "Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts. You will be known as {name} of the Shattered Sun if you complete this quest.", progress = "Are you ready to make the contribution?", completion = "You truly are a generous person and a worthy ally.  From now on you shall be known as {name} of the Shattered Sun and all who fought here will know of your deeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[11550] = { id = 11550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter, the Deceiver...", description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.", sourceObjective = "Report to Archmage Ne'thul on the Isle of Quel'Danas, north of Quel'Thalas.\n\nFlight masters in Ironforge and Silvermoon City will get you to your destination.", completion = "Kil'jaeden bears down upon this world with the full force of the Burning Legion. Should the summoning complete, our world will once more be flung into the throes of chaos. Your assistance on the Isle of Quel'Danas is critical to our success against the Burning Legion.\n\nOur mages are working on bringing down the barriers blocking access to the Sunwell. Do your part in battling the forces of the Legion by helping the Shattered Sun Offensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11551] = { id = 11551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamath, the First Gate" }
quests[11554] = { id = 11554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend in the Frontlines", sourceObjective = "Your aid in the offensive has not gone unnoticed, {name}.  The combined forces of the Aldor and Scryers offer you their thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11555] = { id = 11555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored by Your Allies", sourceObjective = "You continue to prove yourself in this most important battle, {name}.  Please accept this as a token of our continued gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11556] = { id = 11556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered in the Field of Battle", sourceObjective = "We couldn't have gotten where we are without you, {name}.  The combined might of the Aldor and Scryers is not enough to crush the Legion and Kael.  We are thankful to have allies of your caliber among us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11557] = { id = 11557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted Among All Combatants", sourceObjective = "You are one of our very best, {name}.  Your name will be known throughout our ranks for a long time to come.\n\nPlease accept this small gift on the behalf of our forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[11558] = { id = 11558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", sourceObjective = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this.", sourceObjectiveStatus = "unverified-source-field" }
quests[11580] = { id = 11580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Silverpine bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11581] = { id = 11581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Westfall bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11583] = { id = 11583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Westfall flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11584] = { id = 11584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Silverpine Forest flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11657] = { id = 11657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.\n\nCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!", sourceObjective = "Catch 4 torches in a row, then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11665] = { id = 11665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisks in the City", description = "Hello <lad/lass>.  I'm glad you've stopped by to talk to this old man--there's trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.", sourceObjective = "Bring a Baby Crocolisk to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Catch any crocs in the sewers yet?", completion = "What a mean little creature!  I'm sure the Rokk will make something tasty with him.\n\nI'm just kidding, of course.\n\n<Old Man Barlo winks slyly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11666] = { id = 11666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait Bandits", description = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.", sourceObjective = "Bring a Blackfin Darter to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "How's the fishing today, lad?", completion = "Well look at that... you caught a big one!  This old man is eating in style tonight.", sourceObjectiveStatus = "unverified-source-field" }
quests[11667] = { id = 11667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.\n\nYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", sourceObjective = "Catch the World's Largest Mudfish and bring it to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Tell me you caught him.  Please tell me you caught that son of a carp.", completion = "There he is!  I'd know that scar anywhere.\n\nTo be completely honest, I thought he'd be... bigger.  Well, I suppose I'll let him go and try again another day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11668] = { id = 11668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrimpin' Ain't Easy", description = "There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?\n\nShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", sourceObjective = "Bring 10 Giant Freshwater Shrimp to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "What's the catch of the day, lad?", completion = "You are skilled with both the hook and knife.  Hand those sweet tidbits over, and I'll let you have a taste.", sourceObjectiveStatus = "unverified-source-field" }
quests[11669] = { id = 11669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felblood Fillet", description = "This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.", sourceObjective = "Bring a Monstrous Felblood Snapper to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "The felblood is a marvel of evolution.  It can survive in any water and even lava, and fishermen are its only natural predator.\n\nAny luck with your prey?", completion = "That is the biggest, ugliest fish I've seen.  I can't even imagine what you used for bait.\n\nJust set the beast on the ground, and I'll deal with it once I'm sure it's dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11691] = { id = 11691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Ahune", description = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  {name}, you will be the fist of the Earthmother.\n\nTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.\n\nIf fortune is with us, then, perhaps, we can defeat him.\n\nPrepare yourself, {name}.  If Ahune comes to face us, then his fury will be great.", sourceObjective = "Bring the Earthen Ring Magma Totem to the Ice Stone.", progress = "This shard of ice echoes the deep, cracking rumble of invading glaciers.  Its cold turns your thoughts to a lifeless, endless winter.", completion = "The magma totem bursts into three separate flames as it is brought near the ice stone.  The stone shimmers, then is gone...", sourceObjectiveStatus = "unverified-source-field" }
quests[11696] = { id = 11696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune is Here!", description = "{name}, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, {name}.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.", sourceObjective = "Find Luma Skymother in the Slave Pens.", completion = "The cold of Ahune spreads through these caverns, {name}; a seed of the frigid death that awaits us if he gains his full strength.  I thank the Earthmother for sending you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lession.", sourceObjective = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", sourceObjectiveStatus = "unverified-source-field" }
quests[11732] = { id = 11732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Arathi Highlands bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11734] = { id = 11734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Ashenvale bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11735] = { id = 11735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Azuremyst Isle bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11736] = { id = 11736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Blade's Edge Mountains bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11737] = { id = 11737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Blasted Lands bonfire!", sourceObjectiveStatus = "unverified-source-field" }
