quests[11863] = { id = 11863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Zangarmarsh flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11875] = { id = 11875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining the Advantage", description = "The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops.\n\nThe key ingredient, nether residue, pervades Outland  -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying <his/her> trade. Those herbs, ores, and beasts native to Outland may all bear the residue.", sourceObjective = "Bring 8 Nether Residue to Emissary Mordin in Shattrath City.", progress = "Have you any residue for me?", completion = "Thank you for your help, {name}. No contribution to the war effort is too small. Our men are going to need every advantage they can get in this battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[11877] = { id = 11877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Attack Plans", description = "As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.\n\nWe must not allow this to happen, {name}. Each and every blade is needed on the front lines.\n\nGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, {name}.", sourceObjective = "Lord Torvos in Shattrath wants you to capture the Sunfury Attack Plans.", progress = "Have you returned with the plans?", completion = "<Lord Torvos accepts the plans and looks over them.>\n\nYou've done the offensive a great service, {name}, but we should not rest. I wouldn't put it beyond our foes to plan more mischief in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[11880] = { id = 11880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Multiphase Survey", description = "I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand.\n\nAccording to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?", sourceObjective = "Harbinger Haronem in Shattrath City wants you to use the Multiphase Spectrographic Goggles to take 6 Multiphase Readings.", progress = "Did you get those readings? That gnome will scream at me again if I don't get his precious data.", completion = "Thanks for your help. You don't know what it's like to have to deal with \"Doctor\" Wafflefry over there. In between his \"checkups\" on my progress, he's busy hawking some gadget or another derived from his military inventions.", sourceObjectiveStatus = "unverified-source-field" }
quests[11882] = { id = 11882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.", sourceObjective = "Speak to a Master Fire Eater in any Alliance capital.", completion = "Well met. You've come learn some new ways to handle fire?", sourceObjectiveStatus = "unverified-source-field" }
quests[11883] = { id = 11883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Dancing?", description = "You wish the learn the art of fire dancing?\n\nWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.", sourceObjective = "Speak to a Master Fire Dancer in any Horde capital.", sourceObjectiveStatus = "unverified-source-field" }
quests[11885] = { id = 11885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  These are powerful beings you will be facing; you would do well to bring friends.", sourceObjective = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing.", progress = "Have you completed your task, {name}?", completion = "Excellent!  Take this.  I've prepared this bundle with items symbolizing the foes you've defeated.  They will allow you to summon Terokk.\n\nBeware, {name}.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11886] = { id = 11886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Activity", description = "While celebration has its place, {class}, some of us must look to graver matters.\n\nWhen the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.", sourceObjective = "Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon.", progress = "What have you uncovered?", completion = "This is worrisome, friend. It hints at a much larger plot beyond simple agitation of the local fire and water elements, and something here bears investigation...", sourceObjectiveStatus = "unverified-source-field" }
quests[11891] = { id = 11891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Innocent Disguise", description = "According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests?\n\nMuch could be learned from listening to these proceedings, {race}. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.", sourceObjective = "Use the Orb of the Crawler to spy upon the new Twilight camp to the west of the Blackfathom Deeps entrance on the Zoram Strand in Ashenvale, then summon the Earthen Ring Guide using the Totemic Beacon.", progress = "Have you learned their secrets?", completion = "They seek to summon a frost lord into our world? No! They cannot tip the balance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11915] = { id = 11915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.", sourceObjective = "Speak to a Master Flame Eater in any Horde capital.", completion = "Greetings. You've come learn some new ways to handle fire?", sourceObjectiveStatus = "unverified-source-field" }
quests[11917] = { id = 11917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nReturn to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Frostwave Lieutenant summoned from the Ice Stone located on Zoram Strand in Ashenvale, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11921] = { id = 11921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", sourceObjective = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", sourceObjectiveStatus = "unverified-source-field" }
quests[11922] = { id = 11922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lession.", sourceObjective = "Win the torch tossing game, then speak with the Master Flame Eater.", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", sourceObjectiveStatus = "unverified-source-field" }
quests[11923] = { id = 11923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.\n\nCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!", sourceObjective = "Catch 4 torches in a row, then speak with the Master Flame Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11924] = { id = 11924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", sourceObjective = "Catch 10 torches in a row, then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, {name}?  You looked great out there.  A real juggling master!", sourceObjectiveStatus = "unverified-source-field" }
quests[11925] = { id = 11925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", sourceObjective = "Catch 10 torches in a row, then speak with the Master Flame Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, {name}?  You looked great out there.  A real juggling master!", sourceObjectiveStatus = "unverified-source-field" }
quests[11926] = { id = 11926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", sourceObjective = "Win the torch tossing game, then speak with the Master Flame Eater.", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", sourceObjectiveStatus = "unverified-source-field" }
quests[11933] = { id = 11933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Exodar's Flame", description = "This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", sourceObjective = "Return the Flame of the Exodar to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire seems new... Yet, you say it came from the Exodar? Fascinating! To make your way into that ship...  Of course, I'll pay you for this. If you find anything else like this, be sure to speak with me again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11935] = { id = 11935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Silvermoon's Flame", description = "This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", sourceObjective = "Return the Flame of Silvermoon to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "What a glorious fire! You received this from Silvermoon, you say? Unbelievable! With the flames of all four cities, who knows what we could accomplish?", sourceObjectiveStatus = "unverified-source-field" }
quests[11947] = { id = 11947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nThere is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Hailstone Lieutenant summoned from the Ice Stone located at Ethel Rethor in Desolace, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11948] = { id = 11948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nNeptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Chillwind Lieutenant summoned from the Ice Stone located on the water elemental's island in western Stranglethorn Vale, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11952] = { id = 11952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nFirewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Frigid Lieutenant summoned from the Ice Stone located in the cave underneath Firewatch Ridge in the northwest of Searing Gorge, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11953] = { id = 11953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nSilithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Glacial Lieutenant summoned from the Ice Stone located at Twilight's Run in northern Silithus, then return to the Earthen Ring Elder in a capital city.", progress = "You have returned victorious?", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11954] = { id = 11954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nIn order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Glacial Templar summoned from the Ice Stone located near the Dark Portal in Hellfire Peninsula, then return to the Earthen Ring Elder in a capital city.", progress = "You have returned victorious?", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11955] = { id = 11955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune, the Frost Lord", description = "I believe you are strong enough for the ultimate task set before us.\n\nWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!", sourceObjective = "Travel to the Slave Pens in Coilfang Reservoir within Zangarmarsh and speak with Numa Cloudsister.", completion = "Thank the spirits you're here! We must summon Ahune quickly before it's too late...", sourceObjectiveStatus = "unverified-source-field" }
quests[11964] = { id = 11964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense for the Summer Scorchlings", description = "Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.", sourceObjective = "The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement.", progress = "A fiery salutations to you, honored {class}.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, {name}.  Take it, and leave me be... I must attend to this precious fuel...", sourceObjectiveStatus = "unverified-source-field" }
quests[11966] = { id = 11966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense for the Festival Scorchlings", description = "Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.", sourceObjective = "The Festival Talespinner wants you to take Summer Incense to a Festival Scorchling outside any Horde settlement.", progress = "A fiery salutations to you, honored {class}.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, {name}.  Take it, and leave me be... I must attend to this precious fuel...", sourceObjectiveStatus = "unverified-source-field" }
quests[11970] = { id = 11970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Summer Lore", description = "The festival is a time for fun and laughter, there's no mistake. It's important, however, that you understand the origins of this holiday. Education should be sought out and savored.\n\nThe Festival Loremaster in the Alliance capitals can guide your way. Go now and learn.", sourceObjective = "Speak to the Festival Loremaster in any Alliance capital.", completion = "I'll be happy to tell you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11971] = { id = 11971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spinner of Summer Tales", description = "The festival is a time for fun and laughter, there's no mistake. It's important, however, that you understand the origins of this holiday. Education should be sought out and savored.\n\nThe Festival Talespinner in the Horde capitals can guide your way. Go now and learn.", sourceObjective = "Speak to the Festival Talespinner in any Horde capital.", completion = "I'll be happy to tell you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11972] = { id = 11972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of Ahune", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?", sourceObjective = "Bring the Ice Shards to Luma Skymother.", progress = "Greetings, {name}.  You look worried, but you shoud rejoice.  The Frost Lord is defeated!", completion = "Yes, these shards hold the final essence of the Frost Lord in this land.  We will dispose of them and banish Ahune to the nether regions of cold.\n\nThank you, {name}.  Your name will echo in the chants of the Earthen Ring for days without end.  Please honor us by accepting this vestige, a symbol of your kinship with warmth and light.", sourceObjectiveStatus = "unverified-source-field" }
quests[11975] = { id = 11975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now, When I Grow Up...", description = "Maybe I already asked you this, but when you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Elite Tauren Chieftain!\n\nI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.\n\nPlease take me there.  Please!", sourceObjective = "Take your orphan, Salandria, to see the Elite Tauren Chieftain in Silvermoon City's Walk of Elders. Make sure to call for her if she is not present when you arrive.Maybe I already asked you this, but when you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be. Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Elite Tauren Chieftain!\n\nI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.\n\nPlease take me there. Please!", progress = "Elite {race} Chieftain are the coolest!", completion = "Did you see that?  They were cheering for me!!\n\nNow I know how they feel when they are up on stage singing!  I felt the power and the energy!\n\nJust like they say in their song!\n\nMy mind is made up, I am going to be a rock star when I grow up!", sourceObjectiveStatus = "unverified-source-field" }
quests[11976] = { id = 11976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Shards", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?", sourceObjective = "Bring the Ice Shards to Luma Skymother.", sourceObjectiveStatus = "unverified-source-field" }
quests[12012] = { id = 12012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", sourceObjective = "Travel to a capital city and return the Totemic Beacon to the Earthen Ring Elder.", progress = "What troubles you, my child?", completion = "This is grave news indeed. We must do everything in our power to stop this war from coming to pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[12020] = { id = 12020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Boxey and explain your heroic triumph over the Dark Iron dwarves.", sourceObjective = "Talk to Boxey Boltspinner in the Brewfest camp.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, {class}, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, {name}.  Enjoy the rest of Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12022] = { id = 12022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chug and Chuck!", description = "Hey there!  You look like you can handle your brew.  But can you handle your brew mug? \n\nThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.\n\nIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.", sourceObjective = "Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.", progress = "Toss one back, then toss one forward.  S.T.O.U.T. can take the abuse, it's why I built him.", completion = "Do you know what that was?  Gnomish engineering at its finest!  S.T.O.U.T. took the abuse like a champ!\n\nI think you're ready now to take on the Dark Irons if they show up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[12062] = { id = 12062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insult Coren Direbrew", description = "Coren Direbrew is in the next room, riling up Dark Iron dwarves for another attack on Brewfest.  Defeat him!\n\nGo to Coren and pick a fight.  Tell him his beer isn't fit for pigs.\n\nWhen you do that, be ready for a fight.  The last person who insulted his brew... was fed to dire boars.", sourceObjective = "Speak with Coren Direbrew.", completion = "What?  What did you say?  How dare you!  My beer can stand up to any of that rot they serve at Brewfest!\n\nYou'll pay for this insult, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12133] = { id = 12133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpking reveals an old, scorched holy symbol.", sourceObjective = "Give the Scorched Holy Symbol to the Costumed Orphan Matron.", progress = "Yes, {name}?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  If must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, {name}.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself.", sourceObjectiveStatus = "unverified-source-field" }
quests[12135] = { id = 12135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Let the Fires Come!\"", description = "You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe!\n\nPlease, {name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", sourceObjective = "The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them. When they are out, speak again to the Costumed Orphan Matron.", progress = "{name}, you promised to save the children!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.", sourceObjectiveStatus = "unverified-source-field" }
quests[12139] = { id = 12139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Let the Fires Come!\"", description = "The Headless Horseman will attack the village at any moment!  Fires will be everywhere!\n\n{name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", sourceObjective = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", progress = "The Horde's children need you!  Do not abandon them!", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today.", sourceObjectiveStatus = "unverified-source-field" }
quests[12155] = { id = 12155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpking reveals an old, scorched holy symbol.", sourceObjective = "Give the Scorched Holy Symbol to the Masked Orphan Matron.", progress = "Yes, {name}?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  If must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, {name}.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself.", sourceObjectiveStatus = "unverified-source-field" }
quests[12191] = { id = 12191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chug and Chuck!", description = "Those pesky Dark Irons are back!  We need to make sure that you can defend yourself if needed.  More importantly, we need to know that you can defend our property!\n\nS.T.O.U.T. here is ready for action, are you?  Drink from the Complimentary Brewfest Samplers then throw the mug at S.T.O.U.T.!  Hit the target 5 times then talk to me.", sourceObjective = "Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Bizzle Quicklift.", progress = "Chug from the mug, then chuck the mug at S.T.O.U.T.  I think he can withstand the pounding.  I wouldn't have stol.. er... built him if he couldn't!", completion = "Wow...  S.T.O.U.T. didn't break... Hmm... Who would have guessed?\n\nI mean, hey, you did it!  Your aim is true, or at least true enough to help guard the camp.  I think you're ready now to take on the Dark Irons if they show up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[12192] = { id = 12192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.", sourceObjective = "Talk to Bizzle Quicklift in the Brewfest camp.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, {class}, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, {name}.  Enjoy the rest of Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12193] = { id = 12193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "Aww, it's just a stein voucher... Maybe you're just playing hard to get.  So here's this year's stein for you.\n\nBut I suspect I'll be seeing a lot more of you.  After all, if you want any Brewfest tokens redeemed, I'm your girl...\n\nOr maybe I'm his girl...  \n\nOooohhh... or his...", sourceObjectiveStatus = "unverified-source-field" }
quests[12194] = { id = 12194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "What's this?  A stein voucher?  So you like drinking?  Great!  After I give you this stein, go have a few drinks!  Then a few more.  Maybe have a few more after that...  Then, now this is important, come see me.\n\nLook, I know you'll be back eventually.  If you want your Brewfest tokens redeemed you have to see me.\n\nAnyways, here's the stein, and remember to talk to me later.", sourceObjectiveStatus = "unverified-source-field" }
quests[12278] = { id = 12278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", sourceObjective = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12286] = { id = 12286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12306] = { id = 12306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.", sourceObjective = "Bring the \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Brewfest!", description = "{name}, our spies have discovered a fiendish plot!  The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths.  Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths.  He'll know more of Direbrew's plot.\n\nFind our spy.  Save Brewfest!", sourceObjective = "Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths.", completion = "You're from the Brewfest camp? Glory day!  Brewfest may yet be saved.\n\n{name}, Coren Direbrew must be stopped!  We cannot let him sabotage our sacred holiday.  Our brews must flow!", sourceObjectiveStatus = "unverified-source-field" }
quests[12331] = { id = 12331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
